using System.Text;

namespace PhotoSiftReborn;

/// <summary>
/// Cohesive candidate execution lane for sealed GENERATED bytes only. All
/// ordinary coordinators retain their original authorizations. Serial store
/// ownership, local same-device filesystems, bounded history; never auto replay.
/// </summary>
internal sealed class R30GeneratedOperationCoordinator
{
    private readonly WorkspaceSessionStore _db;
    private readonly Action<string>? _cut;
    private string? _executionCheckpoint;
    internal R30GeneratedOperationCoordinator(WorkspaceSessionStore db,Action<string>? cut=null)
    {
        _db=db;_cut=cut;_ = db.R30Load();
    }
    private void Cut(string value)=>_cut?.Invoke(value);

    internal static SortingWorkspace ProvisionGeneratedFixture(WorkspaceSessionStore db,int count=16)
    {
        var root=Directory.GetParent(Path.GetDirectoryName(db.DatabasePath)!)!.FullName;
        string name=Path.GetFileName(root);const string prefix="PHOTOSIFT_REBORN_P1_DISPOSABLE_";
        if(count is <4 or >256 || !name.StartsWith(prefix,StringComparison.Ordinal) ||
            !Guid.TryParseExact(name[prefix.Length..],"N",out _) ||
            !SortingWorkspace.PathComparer.Equals(Directory.GetParent(root)?.FullName,
                Path.TrimEndingDirectorySeparator(Path.GetFullPath(Path.GetTempPath()))) ||
            SortingWorkspace.HasLinkedExistingAncestor(root) ||
            Directory.EnumerateFileSystemEntries(root).Any(x=>Path.GetFileName(x)!="state"))
            throw new IOException("R30 provisioning requires a fresh generated-only disposable root.");
        db.R30RequirePristineGeneratedStore();
        var directories=new[]{root,Path.Combine(root,"state"),Path.Combine(root,"source"),
            Path.Combine(root,"output"),Path.Combine(root,"r30-recovery")};
        foreach(var dir in directories)Directory.CreateDirectory(dir);
        // Deterministic generated PNG plus per-file provenance bytes; no photo
        // input is accepted by this provisioning API.
        byte[] png=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aT1sAAAAASUVORK5CYII=");
        for(int i=0;i<count;i++)
        {
            using var fs=new FileStream(Path.Combine(root,"source",$"r30-{i:D3}.png"),FileMode.CreateNew);
            fs.Write(png);fs.Write(Encoding.UTF8.GetBytes($"\nPhotoSift R30 generated seed {i}\n"));fs.Flush(true);
        }
        var work=new SortingWorkspace {IdentityResolver=NativeFileCapability.Identity};
        work.OpenSource(Path.Combine(root,"source"));work.SetDestinationRoot(Path.Combine(root,"output"));
        db.Save(work.CaptureSession());
        var fixture=new R30Fixture(db.MoveInstallationId(),root,directories.Select(x=>
            new R30DirectoryPin(x,NativeFileCapability.DirectoryIdentity(x))).ToArray(),
            work.Photos.Select(p=>new R30Seed(p.Path,p.NativeIdentity!,R30Native.Hash(p.Path),
                p.Length,p.LastWriteUtcTicks)).ToArray());
        void Marker(string file,string text)
        {
            using var fs=new FileStream(Path.Combine(root,file),FileMode.CreateNew);
            fs.Write(Encoding.UTF8.GetBytes(text));fs.Flush(true);
        }
        Marker("P3B2_TEST_ONLY.marker","synthetic-interruption-only");
        Marker("R30_GENERATED_ONLY.marker",R30Native.Json(fixture));
        db.R30Enroll(fixture);return work;
    }

    internal R30Plan Prepare(string family,Guid photoId,string? destination=null,Guid? consumes=null)
    {
        var s=_db.R30Load();CheckAll(s);
        if(s.Operations.Length>=512)throw new IOException("R30 bounded history is full.");
        if(family is not ("Copy" or "Move" or "Rename" or "Reject"))throw new IOException("R30 unsupported family.");
        string source,identity,hash;long length,ticks;
        if(consumes is {} parentId)
        {
            var parent=s.Operations.SingleOrDefault(x=>x.Plan.Id==parentId)
                ?? throw new IOException("R30 consumed predecessor absent.");
            if(parent.State!="Committed" || parent.OutputIdentity is null || parent.Plan.Family=="Reject" ||
                R30Native.OutputPath(parent,s.Operations)!=parent.Plan.Destination)
                throw new IOException("R30 consumed-source continuation requires the exact, currently installed predecessor output; recovery archives remain HOLD.");
            source=parent.Plan.Destination;identity=parent.OutputIdentity;hash=parent.Plan.Hash;
            length=parent.Plan.Length;ticks=parent.OutputTicks;
            photoId=Guid.NewGuid();
        }
        else
        {
            var photo=s.Saved.Photos.SingleOrDefault(x=>x.Id==photoId)
                ?? throw new IOException("R30 exact saved photo missing.");
            var seed=s.Fixture.Seeds.SingleOrDefault(x=>x.Path==photo.Path)
                ?? throw new IOException("R30 photograph is not a generated seed.");
            if(seed.Identity!=photo.NativeIdentity || seed.Length!=photo.Length || seed.Ticks!=photo.LastWriteUtcTicks)
                throw new IOException("R30 saved photo identity changed.");
            source=seed.Path;identity=seed.Identity;hash=seed.Hash;length=seed.Length;ticks=seed.Ticks;
        }
        var id=Guid.NewGuid();string token=id.ToString("N");
        string root=s.Fixture.Root,recovery=Path.Combine(root,"r30-recovery");
        destination=family switch {
            "Reject"=>Path.Combine(recovery,token+"-reject.png"),
            "Rename"=>destination ?? Path.Combine(Path.GetDirectoryName(source)!,"renamed-"+token+".png"),
            _=>destination ?? Path.Combine(root,"output",token+".png")};
        var p=new R30Plan(id,family,s.Fixture.Installation,s.Saved.SessionId,s.Operations.Length+1,
            photoId,Guid.NewGuid(),s.Saved.Revision,source,destination,
            Path.Combine(Path.GetDirectoryName(destination)!,".r30-"+token+".part"),
            Path.Combine(recovery,token+"-original.png"),Path.Combine(recovery,token+"-output.png"),
            identity,hash,length,ticks,consumes,s.Fixture.Directories);
        Candidate(s,new(p,"Intent"));return p;
    }
    private static string Witness(R30Operation op,string shape)=>R30Native.Digest(R30Native.Json(new {op,shape}));
    internal R30Review Review(R30Plan plan,bool independentlyApproved)
    {
        var operation=new R30Operation(plan,"Intent");
        return _db.R30Approve(operation,"Apply",independentlyApproved,
            s=>Candidate(s,operation),Witness(operation,"Source"));
    }
    private static void Candidate(R30Snapshot s,R30Operation row)
    {
        var p=row.Plan;CheckAll(s);WorkspaceSessionStore.R30ValidatePlan(s.Fixture,p);
        if(p.Installation!=s.Fixture.Installation || p.Session!=s.Saved.SessionId ||
            p.Revision!=s.Saved.Revision || p.Epoch!=s.Operations.Length+1 ||
            s.Operations.Any(x=>x.Plan.Id==p.Id))
            throw new IOException("R30 candidate session/epoch/checkpoint changed.");
        if(p.Consumes is null)
        {
            var seed=s.Fixture.Seeds.SingleOrDefault(x=>x.Path==p.Source);
            var photo=s.Saved.Photos.SingleOrDefault(x=>x.Id==p.Photo);
            if(seed is null || photo is null || photo.Path!=seed.Path ||
                photo.NativeIdentity!=seed.Identity || photo.Length!=seed.Length || photo.LastWriteUtcTicks!=seed.Ticks ||
                seed.Identity!=p.Identity || seed.Hash!=p.Hash || seed.Length!=p.Length || seed.Ticks!=p.Ticks)
                throw new IOException("R30 candidate is not the exact saved generated photograph.");
        }
        else
        {
            var parent=s.Operations.SingleOrDefault(x=>x.Plan.Id==p.Consumes);
            if(parent is null || parent.State!="Committed" || parent.Plan.Family=="Reject" ||
                R30Native.OutputPath(parent,s.Operations)!=parent.Plan.Destination || parent.Plan.Destination!=p.Source ||
                parent.OutputIdentity!=p.Identity || parent.Plan.Hash!=p.Hash ||
                parent.Plan.Length!=p.Length || parent.OutputTicks!=p.Ticks)
                throw new IOException("R30 exact native consumed-source predecessor changed.");
        }
        R30Native.Graph(s.Operations.Append(row).ToArray());Shape(row,s.Operations,"Source");
    }
    private static void CheckAll(R30Snapshot s,R30Operation? target=null,string? shape=null)
    {
        R30Native.Graph(s.Operations);
        var current=target is null?s.Operations:s.Operations.Select(x=>x.Plan.Id==target.Plan.Id?target:x).ToArray();
        foreach(var row in s.Operations)
        {
            if(target is not null && row.Plan.Id==target.Plan.Id)continue;
            R30Native.Terminal(row,current);
        }
        if(target is not null)Shape(target,current,shape!);
    }
    private static void Shape(R30Operation row,IReadOnlyList<R30Operation> history,string shape)
    {
        var p=row.Plan;R30Native.Directories(p.Directories);
        if(shape=="Terminal") {R30Native.Terminal(row,history);return;}
        if(p.Family is "Rename" or "Reject")
        {
            bool installed=shape=="Installed";
            R30Native.Owned(installed?p.Destination:p.Source,p.Identity,p.Hash,p.Length,p.Ticks);
            R30Native.Vacant(installed?p.Source:p.Destination);
            R30Native.Vacant(p.Temp);R30Native.Vacant(p.OriginalArchive);R30Native.Vacant(p.OutputArchive);
            return;
        }
        bool archived=shape is "ArchivedPair" or "ArchivedClean";
        bool pair=shape is "Pair" or "ArchivedPair";
        bool temp=shape is "Temp" || pair;
        bool output=shape is "Pair" or "ArchivedPair" or "Installed" or "ArchivedClean" or "Restored";
        bool undone=shape=="Undone";
        if(archived)
        {
            R30Native.Owned(p.OriginalArchive,p.Identity,p.Hash,p.Length,p.Ticks);R30Native.Vacant(p.Source);
        }
        else
        {
            R30Native.Source(row,history);R30Native.Vacant(p.OriginalArchive);
        }
        if(temp)R30Native.Owned(p.Temp,row.TempIdentity,p.Hash,p.Length,publicationPair:pair);
        else R30Native.Vacant(p.Temp);
        if(output)R30Native.Owned(p.Destination,row.OutputIdentity ?? row.TempIdentity,p.Hash,p.Length,
            row.OutputTicks==0?null:row.OutputTicks,publicationPair:pair);
        else R30Native.Vacant(p.Destination);
        if(pair && (NativeFileCapability.RegularFileLinkCount(p.Temp)!=2 ||
            NativeFileCapability.RegularFileLinkCount(p.Destination)!=2))
            throw new IOException("R30 publication has an unreviewed extra hard link.");
        if(undone)R30Native.Owned(p.OutputArchive,row.OutputIdentity,p.Hash,p.Length,row.OutputTicks);
        else R30Native.Vacant(p.OutputArchive);
    }
    private void WithReview(R30Review review,Action action) => _db.R30Exclusive(()=>
    {
        if(_executionCheckpoint is not null)throw new IOException("R30 reentrant native execution refused.");
        _executionCheckpoint=review.Checkpoint;
        try{action();}finally{_executionCheckpoint=null;}
    });
    private void ExecutionProof(R30Snapshot s,R30Operation row,string shape)
    {
        if(_executionCheckpoint is null || s.Checkpoint!=_executionCheckpoint)
            throw new IOException("R30 saved checkpoint changed during native execution; preserve interrupted state.");
        CheckAll(s,row,shape);
    }
    private void Fresh(R30Operation row,string shape) => ExecutionProof(_db.R30Load(),row,shape);
    private R30Operation Advance(R30Operation row,R30Operation next,string shape)
    {
        _db.R30Advance(row,next,s=>ExecutionProof(s,next,shape));return next;
    }
    internal R30Operation Execute(R30Review review,Action? afterReviewConsumption=null)
    {
        R30Operation? result=null;
        WithReview(review,()=>
        {
            if(review.Action!="Apply" || review.NativeWitness!=Witness(review.Operation,"Source"))
                throw new IOException("R30 incorrect action or witness.");
            var row=_db.R30Consume(review,"Intent",s=>Candidate(s,review.Operation),afterReviewConsumption);
            Cut("INTENT_DURABLE");result=RunForward(row);
        });return result!;
    }
    private R30Operation RunForward(R30Operation row)
    {
        var p=row.Plan;int steps=0;
        while(row.State!="Committed")
        {
            if(++steps>10)throw new IOException("R30 forward state bound exceeded.");
            switch(row.State)
            {
                case "Intent" when p.Family is "Copy" or "Move":
                    Fresh(row,"Source");
                    using(var input=new FileStream(p.Source,FileMode.Open,FileAccess.Read,FileShare.Read))
                    using(var temp=new FileStream(p.Temp,FileMode.CreateNew,FileAccess.Write,FileShare.None))
                    {input.CopyTo(temp);temp.Flush(true);}
                    Cut("TEMP_CREATED_UNACKNOWLEDGED");
                    row=Advance(row,row with {State="TempReady",TempIdentity=NativeFileCapability.Identity(p.Temp)},"Temp");Cut("TEMP_DURABLE");
                    break;
                case "Intent":
                    Fresh(row,"Source");Relocate(p,p.Source,p.Destination,p.Identity,p.Ticks);
                    Cut("RELOCATED_UNACKNOWLEDGED");
                    row=Advance(row,row with {State="Committed",OutputIdentity=p.Identity,OutputTicks=p.Ticks},"Installed");break;
                case "TempReady":
                    row=Advance(row,row with {State="PublishIntent"},"Temp");Cut("PUBLISH_INTENT_DURABLE");break;
                case "PublishIntent":
                    Fresh(row,"Temp");NativeFileCapability.PublishLinkNoReplace(p.Temp,p.Destination);
                    Cut("PUBLISHED_UNACKNOWLEDGED");
                    row=Advance(row,row with {State="Published",OutputIdentity=row.TempIdentity,
                        OutputTicks=new FileInfo(p.Destination).LastWriteTimeUtc.Ticks},"Pair");Cut("PUBLISHED_DURABLE");break;
                case "Published" when p.Family=="Move":
                    row=Advance(row,row with {State="ArchiveIntent"},"Pair");Cut("ARCHIVE_INTENT_DURABLE");
                    break;
                case "ArchiveIntent":
                    Fresh(row,"Pair");Relocate(p,p.Source,p.OriginalArchive,p.Identity,p.Ticks);
                    Cut("ORIGINAL_ARCHIVED_UNACKNOWLEDGED");
                    row=Advance(row,row with {State="SourceArchived"},"ArchivedPair");Cut("ORIGINAL_ARCHIVED_DURABLE");
                    break;
                case "Published" or "SourceArchived":
                    row=Advance(row,row with {State="CleanupIntent"},p.Family=="Move"?"ArchivedPair":"Pair");Cut("CLEANUP_INTENT_DURABLE");break;
                case "CleanupIntent":
                    Fresh(row,p.Family=="Move"?"ArchivedPair":"Pair");File.Delete(p.Temp);Cut("TEMP_REMOVED_UNACKNOWLEDGED");
                    row=Advance(row,row with {State="Committed"},p.Family=="Move"?"ArchivedClean":"Installed");break;
                default:throw new IOException("R30 unsupported forward state; no replay.");
            }
        }
        Cut("COMMITTED_DURABLE");Fresh(row,"Terminal");return row;
    }
    private static void Relocate(R30Plan p,string from,string to,string identity,long ticks)
    {
        R30Native.Owned(from,identity,p.Hash,p.Length,ticks);R30Native.Vacant(to);
        R30Native.Directories(p.Directories);
        if(NativeFileCapability.DeviceId(from)!=NativeFileCapability.DeviceId(Path.GetDirectoryName(to)!))
            throw new IOException("R30 cross-device relocation refused.");
        NativeFileCapability.RelocateNoReplaceOwnedBetweenDirectories(from,to,identity,p.Hash,p.Length,ticks,
            p.Directories.Single(x=>SortingWorkspace.PathComparer.Equals(x.Path,Path.GetDirectoryName(from))).Identity,
            p.Directories.Single(x=>SortingWorkspace.PathComparer.Equals(x.Path,Path.GetDirectoryName(to))).Identity);
        R30Native.Owned(to,identity,p.Hash,p.Length,ticks);R30Native.Vacant(from);
    }
    private static void UndoCandidate(R30Snapshot s,R30Operation target)
    {
        CheckAll(s);
        if(target.State!="Committed" || !s.Operations.Any(x=>R30Native.Json(x)==R30Native.Json(target)))
            throw new IOException("R30 exact committed Undo target missing.");
        var pending=new Queue<Guid>();pending.Enqueue(target.Plan.Id);var seen=new HashSet<Guid>();
        while(pending.Count>0)
        {
            var parent=pending.Dequeue();if(!seen.Add(parent))throw new IOException("R30 dependency cycle.");
            foreach(var child in s.Operations.Where(x=>x.Plan.Consumes==parent))
            {
                if(child.State!="Undone")throw new IOException("R30 active dependent "+child.Plan.Id+" must be resolved before Undo.");
                pending.Enqueue(child.Plan.Id);
            }
        }
    }
    internal R30Review ReviewUndo(string family,Guid id,bool independentlyApproved)
    {
        var s=_db.R30Load();var row=s.Operations.SingleOrDefault(x=>x.Plan.Id==id && x.Plan.Family==family)
            ?? throw new IOException("R30 exact family/UUID target absent.");
        return _db.R30Approve(row,"Undo",independentlyApproved,x=>UndoCandidate(x,row),Witness(row,"Terminal"));
    }
    internal R30Operation Undo(R30Review review)
    {
        R30Operation? result=null;
        WithReview(review,()=>
        {
            if(review.Action!="Undo" || review.NativeWitness!=Witness(review.Operation,"Terminal"))
                throw new IOException("R30 exact Undo review missing.");
            var row=_db.R30Consume(review,"UndoIntent",s=>UndoCandidate(s,review.Operation));
            Cut("UNDO_INTENT_DURABLE");result=RunUndo(row);
        });return result!;
    }
    private R30Operation RunUndo(R30Operation row)
    {
        var p=row.Plan;int steps=0;
        while(row.State!="Undone")
        {
            if(++steps>4)throw new IOException("R30 Undo state bound exceeded.");
            if(p.Family=="Move" && row.State=="UndoIntent")
            {
                Fresh(row,"ArchivedClean");Relocate(p,p.OriginalArchive,p.Source,p.Identity,p.Ticks);
                Cut("UNDO_SOURCE_RESTORED_UNACKNOWLEDGED");
                row=Advance(row,row with {State="SourceRestored"},"Restored");Cut("UNDO_SOURCE_RESTORED_DURABLE");
                continue;
            }
            if(p.Family=="Move" && row.State=="SourceRestored")
            {
                row=Advance(row,row with {State="UndoOutputIntent"},"Restored");Cut("UNDO_OUTPUT_INTENT_DURABLE");
                continue;
            }
            if(row.State!=(p.Family=="Move"?"UndoOutputIntent":"UndoIntent"))
                throw new IOException("R30 unsupported Undo state; no replay.");
            if(p.Family is "Copy" or "Move")
            {
                Fresh(row,p.Family=="Move"?"Restored":"Installed");
                Relocate(p,p.Destination,p.OutputArchive,row.OutputIdentity!,row.OutputTicks);
            }
            else
            {
                Fresh(row,"Installed");Relocate(p,p.Destination,p.Source,p.Identity,p.Ticks);
            }
            Cut("UNDO_RELOCATED_UNACKNOWLEDGED");
            row=Advance(row,row with {State="Undone"},p.Family is "Copy" or "Move"?"Undone":"Source");
        }
        Cut("UNDONE_DURABLE");Fresh(row,"Terminal");return row;
    }

    // Inspect a SINGLE fully pinned physical shape, then require separate
    // durable human review before continuing it. The normal Apply/Undo entry
    // points can never consume these reviews or retry an interrupted step.
    private static (R30Operation Row,string Shape) ContinuationObservation(R30Operation row)
    {
        var p=row.Plan;
        return row.State switch {
            "Intent" when p.Family is "Rename" or "Reject" && !File.Exists(p.Source)
                =>(row with {State="Committed",OutputIdentity=p.Identity,OutputTicks=p.Ticks},"Terminal"),
            "Intent"=>(row,"Source"),
            "TempReady"=>(row,"Temp"),
            "PublishIntent" when File.Exists(p.Destination)=>(row with {State="Published",
                OutputIdentity=row.TempIdentity,OutputTicks=new FileInfo(p.Destination).LastWriteTimeUtc.Ticks},"Pair"),
            "PublishIntent"=>(row,"Temp"),
            "Published"=>(row,"Pair"),
            "ArchiveIntent" when !File.Exists(p.Source)=>(row with {State="SourceArchived"},"ArchivedPair"),
            "ArchiveIntent"=>(row,"Pair"),
            "SourceArchived"=>(row,"ArchivedPair"),
            "CleanupIntent" when !File.Exists(p.Temp)=>(row with {State="Committed"},"Terminal"),
            "CleanupIntent"=>(row,p.Family=="Move"?"ArchivedPair":"Pair"),
            "UndoIntent" when p.Family=="Move" && File.Exists(p.Source)=>(row with {State="SourceRestored"},"Restored"),
            "UndoIntent" when p.Family=="Move"=>(row,"ArchivedClean"),
            "UndoIntent" when !File.Exists(p.Destination)=>(row with {State="Undone"},"Terminal"),
            "UndoIntent"=>(row,"Installed"),
            "SourceRestored"=>(row,"Restored"),
            "UndoOutputIntent" when !File.Exists(p.Destination)=>(row with {State="Undone"},"Terminal"),
            "UndoOutputIntent"=>(row,"Restored"),
            _=>throw new IOException("R30 terminal/unsupported state cannot acquire continuation authority.")};
    }
    private static (R30Operation Row,string Shape) ContinuationCandidate(R30Snapshot s,R30Operation original)
    {
        if(!s.Operations.Any(x=>R30Native.Json(x)==R30Native.Json(original)))
            throw new IOException("R30 exact interrupted operation changed.");
        var observed=ContinuationObservation(original);CheckAll(s,observed.Row,observed.Shape);return observed;
    }
    internal R30Review ReviewContinuation(string family,Guid id,bool independentlyApproved)
    {
        var s=_db.R30Load();var row=s.Operations.SingleOrDefault(x=>x.Plan.Id==id && x.Plan.Family==family)
            ?? throw new IOException("R30 exact continuation target absent.");
        var observation=ContinuationCandidate(s,row);
        return _db.R30Approve(row,"Continue/"+row.State,independentlyApproved,x=>
        {
            var fresh=ContinuationCandidate(x,row);
            if(Witness(fresh.Row,fresh.Shape)!=Witness(observation.Row,observation.Shape))
                throw new IOException("R30 native continuation changed during review.");
        },Witness(observation.Row,observation.Shape));
    }
    internal R30Operation Continue(R30Review review)
    {
        R30Operation? result=null;
        WithReview(review,()=>
        {
            if(review.Action!="Continue/"+review.Operation.State)throw new IOException("R30 independent continuation review required.");
            var observed=ContinuationCandidate(_db.R30Load(),review.Operation);
            if(review.NativeWitness!=Witness(observed.Row,observed.Shape))throw new IOException("R30 stale native continuation witness.");
            var row=_db.R30Consume(review,observed.Row.State,s=>
            {
                var fresh=ContinuationCandidate(s,review.Operation);
                if(review.NativeWitness!=Witness(fresh.Row,fresh.Shape))throw new IOException("R30 continuation changed before durable consumption.");
            },terminal:observed.Row);
            Cut("CONTINUATION_AUTHORITY_CONSUMED");
            bool undo=review.Operation.State is "UndoIntent" or "SourceRestored" or "UndoOutputIntent";
            result=undo?RunUndo(row):RunForward(row);
        });return result!;
    }

    // Explicit recovery only acknowledges an already completed terminal
    // physical effect. No recovery API here can replay a file mutation. A
    // missing temp identity remains HOLD; the separate continuation entry point
    // requires independently reviewed evidence at supported intermediate cuts.
    private static R30Operation RecoveryTarget(R30Operation row) => row.State switch {
        "Intent" when row.Plan.Family is "Rename" or "Reject" => row with {
            State="Committed",OutputIdentity=row.Plan.Identity,OutputTicks=row.Plan.Ticks},
        "CleanupIntent" => row with {State="Committed"},
        "UndoIntent" when row.Plan.Family!="Move" => row with {State="Undone"},
        "UndoOutputIntent" => row with {State="Undone"},
        _=>throw new IOException("R30 interrupted stage has no independently provable terminal acknowledgement; continuation HOLD.")};
    internal R30Review ReviewRecovery(string family,Guid id,bool independentlyApproved)
    {
        var s=_db.R30Load();var row=s.Operations.SingleOrDefault(x=>x.Plan.Id==id && x.Plan.Family==family)
            ?? throw new IOException("R30 recovery row absent.");
        var terminal=RecoveryTarget(row);
        return _db.R30Approve(row,"Acknowledge/"+row.State,independentlyApproved,
            x=>CheckAll(x,terminal,"Terminal"),Witness(terminal,"Terminal"));
    }
    internal R30Operation AcknowledgeRecovery(R30Review review)
    {
        if(review.Action!="Acknowledge/"+review.Operation.State)throw new IOException("R30 recovery review required.");
        var terminal=RecoveryTarget(review.Operation);
        if(review.NativeWitness!=Witness(terminal,"Terminal"))throw new IOException("R30 recovery witness mismatch.");
        return _db.R30Consume(review,terminal.State,s=>
        {
            if(!s.Operations.Any(x=>R30Native.Json(x)==R30Native.Json(review.Operation)))
                throw new IOException("R30 recovery predecessor changed.");
            CheckAll(s,terminal,"Terminal");
        },terminal:terminal);
    }
}
